import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class SplitITupVariant2 {
    public static void main(String[] args) {
        List<Integer> openPositions = new ArrayList<>();
        List<Integer> closePositions = new ArrayList<>();
        Scanner sc = new Scanner(System.in);
        int countSegments = sc.nextInt();
        String str = sc.next();

        for (int i = 0; i < countSegments; i++) {
            if (str.charAt(i) == '(') {
                openPositions.add(i);
            } else if (str.charAt(i) == ')') {
                closePositions.add(i);
            }
        }

        int totalWords = 0;
        for (String segment : getSegments(str, openPositions, closePositions)) {
            String[] parts = segment.split("_");
            for (String part : parts) {
                if (!part.isEmpty()) {
                    totalWords++;
                }
            }
        }

        int maxWordLength = 0;
        openPositions.add(str.length());
        closePositions.add(0, 0);
        int startIndex = str.charAt(0) == '(' ? 1 : 0;

        for (int i = startIndex; i < closePositions.size(); i++) {
            String segment;
            if (str.charAt(closePositions.get(i)) == ')') {
                segment = str.substring(closePositions.get(i) + 1, openPositions.get(i));
            } else {
                segment = str.substring(closePositions.get(i), openPositions.get(i));
            }
            String[] parts = segment.split("_");
            for (String part : parts) {
                if (part.length() > maxWordLength && !part.contains("(") && !part.contains(")")) {
                    maxWordLength = part.length();
                }
            }
        }
        System.out.println(maxWordLength + " " + totalWords);
    }

    private static List<String> getSegments(String s, List<Integer> starts, List<Integer> ends) {
        List<String> segments = new ArrayList<>();
        for (int i = 0; i < starts.size(); i++) {
            segments.add(s.substring(starts.get(i) + 1, ends.get(i)));
        }
        return segments;
    }
}
